using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using CodeChallenge.Models;
using Microsoft.Extensions.Logging;
using Microsoft.EntityFrameworkCore;
using CodeChallenge.Data;

namespace CodeChallenge.Repositories
{
    public class EmployeeRespository : IEmployeeRepository
    {
        private readonly EmployeeContext _employeeContext;
        private readonly ILogger<IEmployeeRepository> _logger;

        public EmployeeRespository(ILogger<IEmployeeRepository> logger, EmployeeContext employeeContext)
        {
            _employeeContext = employeeContext;
            _logger = logger;
        }

        public Employee Add(Employee employee)
        {
            employee.EmployeeId = Guid.NewGuid().ToString();
            _employeeContext.Employees.Add(employee);
            return employee;
        }

        public Employee GetById(string id)
        {
            return _employeeContext.Employees.SingleOrDefault(e => e.EmployeeId == id);
        }

        public IEnumerable<Employee> GetAll()
        {
            // Loading the full tracked set lets EF fix up each employee's DirectReports navigation.
            return _employeeContext.Employees.ToList();
        }

        public Task SaveAsync()
        {
            return _employeeContext.SaveChangesAsync();
        }

        public Employee Remove(Employee employee)
        {
            return _employeeContext.Remove(employee).Entity;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using CodeChallenge.Services;
using CodeChallenge.Models;

namespace CodeChallenge.Controllers
{
    [ApiController]
    [Route("api/employee")]
    public class EmployeeController : ControllerBase
    {
        private readonly ILogger _logger;
        private readonly IEmployeeService _employeeService;

        public EmployeeController(ILogger<EmployeeController> logger, IEmployeeService employeeService)
        {
            _logger = logger;
            _employeeService = employeeService;
        }

        [HttpPost]
        public IActionResult CreateEmployee([FromBody] Employee employee)
        {
            _logger.LogDebug($"Received employee create request for '{employee.FirstName} {employee.LastName}'");

            _employeeService.Create(employee);

            return CreatedAtRoute("getEmployeeById", new { id = employee.EmployeeId }, employee);
        }

        [HttpGet("{id}", Name = "getEmployeeById")]
        public IActionResult GetEmployeeById(String id)
        {
            _logger.LogDebug($"Received employee get request for '{id}'");

            var employee = _employeeService.GetById(id);

            if (employee == null)
                return NotFound();

            return Ok(employee);
        }

        // The report count is calculated for this response and is not stored.
        [HttpGet("{id}/reporting-structure")]
        public IActionResult GetReportingStructureById(String id)
        {
            _logger.LogDebug($"Received reporting structure request for '{id}'");

            var reportingStructure = _employeeService.GetReportingStructure(id);
            if (reportingStructure == null)
                return NotFound();

            return Ok(reportingStructure);
        }

        [HttpPut("{id}")]
        public IActionResult ReplaceEmployee(String id, [FromBody]Employee newEmployee)
        {
            _logger.LogDebug($"Recieved employee update request for '{id}'");

            var existingEmployee = _employeeService.GetById(id);
            if (existingEmployee == null)
                return NotFound();

            _employeeService.Replace(existingEmployee, newEmployee);

            return Ok(newEmployee);
        }
    }
}

using System;
using CodeChallenge.Models;
using CodeChallenge.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace CodeChallenge.Controllers
{
    [ApiController]
    [Route("api/compensation")]
    public class CompensationController : ControllerBase
    {
        private readonly ILogger<CompensationController> _logger;
        private readonly ICompensationService _compensationService;
        private readonly IEmployeeService _employeeService;

        public CompensationController(
            ILogger<CompensationController> logger,
            ICompensationService compensationService,
            IEmployeeService employeeService)
        {
            _logger = logger;
            _compensationService = compensationService;
            _employeeService = employeeService;
        }

        [HttpPost]
        public IActionResult Create([FromBody] Compensation compensation)
        {
            var employeeId = compensation?.Employee?.EmployeeId;
            if (string.IsNullOrWhiteSpace(employeeId))
            {
                return BadRequest();
            }

            // Resolve the submitted ID to a stored employee instead of trusting client-supplied employee data.
            var employee = _employeeService.GetById(employeeId);
            if (employee == null)
            {
                return NotFound();
            }

            var createdCompensation = _compensationService.Create(compensation, employee);
            if (createdCompensation == null)
            {
                return Conflict();
            }

            _logger.LogDebug("Created compensation for employee '{EmployeeId}'", employeeId);
            return CreatedAtAction(nameof(GetByEmployeeId), new { employeeId }, createdCompensation);
        }

        [HttpGet("{employeeId}")]
        public IActionResult GetByEmployeeId(string employeeId)
        {
            _logger.LogDebug("Received compensation request for employee '{EmployeeId}'", employeeId);

            var compensation = _compensationService.GetByEmployeeId(employeeId);
            if (compensation == null)
            {
                return NotFound();
            }

            return Ok(compensation);
        }
    }
}

using CodeChallenge.Models;
using CodeChallenge.Repositories;

namespace CodeChallenge.Services
{
    public class CompensationService : ICompensationService
    {
        private readonly ICompensationRepository _compensationRepository;

        public CompensationService(ICompensationRepository compensationRepository)
        {
            _compensationRepository = compensationRepository;
        }

        public Compensation Create(Compensation compensation, Employee employee)
        {
            // EmployeeId is the key, so reject a second compensation for the same employee.
            if (compensation == null || employee == null ||
                _compensationRepository.GetByEmployeeId(employee.EmployeeId) != null)
            {
                return null;
            }

            compensation.Employee = employee;
            compensation.EmployeeId = employee.EmployeeId;
            _compensationRepository.Add(compensation);
            _compensationRepository.SaveAsync().Wait();

            return compensation;
        }

        public Compensation GetByEmployeeId(string employeeId)
        {
            if (string.IsNullOrWhiteSpace(employeeId))
            {
                return null;
            }

            return _compensationRepository.GetByEmployeeId(employeeId);
        }
    }
}

using System.Linq;
using System.Threading.Tasks;
using CodeChallenge.Data;
using CodeChallenge.Models;
using Microsoft.EntityFrameworkCore;

namespace CodeChallenge.Repositories
{
    public class CompensationRepository : ICompensationRepository
    {
        private readonly EmployeeContext _employeeContext;

        public CompensationRepository(EmployeeContext employeeContext)
        {
            _employeeContext = employeeContext;
        }

        public Compensation GetByEmployeeId(string employeeId)
        {
            // Include the related employee so reads return the complete compensation response.
            return _employeeContext.Compensations
                .Include(compensation => compensation.Employee)
                .SingleOrDefault(compensation => compensation.EmployeeId == employeeId);
        }

        public Compensation Add(Compensation compensation)
        {
            return _employeeContext.Compensations.Add(compensation).Entity;
        }

        public Task SaveAsync()
        {
            return _employeeContext.SaveChangesAsync();
        }
    }
}

using System;
using System.Net;
using System.Net.Http;
using System.Text;
using CodeChallenge.Models;
using CodeCodeChallenge.Tests.Integration.Extensions;
using CodeCodeChallenge.Tests.Integration.Helpers;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CodeCodeChallenge.Tests.Integration
{
    [TestClass]
    public class CompensationControllerTests
    {
        private static HttpClient _httpClient;
        private static TestServer _testServer;

        [ClassInitialize]
        [System.Diagnostics.CodeAnalysis.SuppressMessage("Style", "IDE0060:Remove unused parameter", Justification = "Required by MSTest.")]
        public static void InitializeClass(TestContext context)
        {
            _testServer = new TestServer();
            _httpClient = _testServer.NewClient();
        }

        [ClassCleanup]
        public static void CleanUpTest()
        {
            _httpClient.Dispose();
            _testServer.Dispose();
        }

        [TestMethod]
        public void CreateCompensation_ThenGetByEmployeeId_ReturnsPersistedCompensation()
        {
            var employee = CreateEmployee();
            var effectiveDate = new DateTime(2024, 3, 15, 0, 0, 0, DateTimeKind.Utc);
            var compensation = new Compensation
            {
                Employee = new Employee { EmployeeId = employee.EmployeeId },
                Salary = 125000.50m,
                EffectiveDate = effectiveDate
            };

            var createResponse = PostCompensation(compensation);

            Assert.AreEqual(HttpStatusCode.Created, createResponse.StatusCode);
            var createdCompensation = createResponse.DeserializeContent<Compensation>();
            Assert.AreEqual(employee.EmployeeId, createdCompensation.Employee.EmployeeId);
            Assert.AreEqual(compensation.Salary, createdCompensation.Salary);
            Assert.AreEqual(effectiveDate, createdCompensation.EffectiveDate.Value);

            var getResponse = _httpClient.GetAsync($"api/compensation/{employee.EmployeeId}").Result;

            Assert.AreEqual(HttpStatusCode.OK, getResponse.StatusCode);
            var persistedCompensation = getResponse.DeserializeContent<Compensation>();
            Assert.AreEqual(employee.EmployeeId, persistedCompensation.Employee.EmployeeId);
            Assert.AreEqual(employee.FirstName, persistedCompensation.Employee.FirstName);
            Assert.AreEqual(compensation.Salary, persistedCompensation.Salary);
            Assert.AreEqual(effectiveDate, persistedCompensation.EffectiveDate.Value);
        }

        [TestMethod]
        public void GetByEmployeeId_WithoutCompensation_ReturnsNotFound()
        {
            var employee = CreateEmployee();

            var response = _httpClient.GetAsync($"api/compensation/{employee.EmployeeId}").Result;

            Assert.AreEqual(HttpStatusCode.NotFound, response.StatusCode);
        }

        [TestMethod]
        public void CreateCompensation_ForUnknownEmployee_ReturnsNotFoundAndDoesNotPersist()
        {
            var employeeId = Guid.NewGuid().ToString();
            var compensation = new Compensation
            {
                Employee = new Employee { EmployeeId = employeeId },
                Salary = 80000m,
                EffectiveDate = DateTime.UtcNow
            };

            var createResponse = PostCompensation(compensation);
            var getResponse = _httpClient.GetAsync($"api/compensation/{employeeId}").Result;

            Assert.AreEqual(HttpStatusCode.NotFound, createResponse.StatusCode);
            Assert.AreEqual(HttpStatusCode.NotFound, getResponse.StatusCode);
        }

        [TestMethod]
        public void CreateCompensation_ForEmployeeWithExistingCompensation_ReturnsConflict()
        {
            var employee = CreateEmployee();
            var compensation = new Compensation
            {
                Employee = new Employee { EmployeeId = employee.EmployeeId },
                Salary = 95000m,
                EffectiveDate = DateTime.UtcNow
            };

            var firstResponse = PostCompensation(compensation);
            var duplicateResponse = PostCompensation(compensation);

            Assert.AreEqual(HttpStatusCode.Created, firstResponse.StatusCode);
            Assert.AreEqual(HttpStatusCode.Conflict, duplicateResponse.StatusCode);
        }

        [TestMethod]
        public void CreateCompensation_WithoutEmployee_ReturnsBadRequest()
        {
            var compensation = new Compensation
            {
                Salary = 95000m,
                EffectiveDate = DateTime.UtcNow
            };

            var response = PostCompensation(compensation);

            Assert.AreEqual(HttpStatusCode.BadRequest, response.StatusCode);
        }

        [TestMethod]
        public void CreateCompensation_WithNonPositiveSalary_ReturnsBadRequest()
        {
            var employee = CreateEmployee();
            var compensation = new Compensation
            {
                Employee = new Employee { EmployeeId = employee.EmployeeId },
                Salary = 0m,
                EffectiveDate = DateTime.UtcNow
            };

            var response = PostCompensation(compensation);

            Assert.AreEqual(HttpStatusCode.BadRequest, response.StatusCode);
        }

        [TestMethod]
        public void CreateCompensation_WithoutEffectiveDate_ReturnsBadRequest()
        {
            var employee = CreateEmployee();
            var compensation = new Compensation
            {
                Employee = new Employee { EmployeeId = employee.EmployeeId },
                Salary = 95000m
            };

            var response = PostCompensation(compensation);

            Assert.AreEqual(HttpStatusCode.BadRequest, response.StatusCode);
        }

        private static Employee CreateEmployee()
        {
            // Each test uses a fresh employee so shared in-memory state cannot affect other cases.
            var employee = new Employee
            {
                FirstName = "Compensation",
                LastName = "Test",
                Department = "Engineering",
                Position = "Developer"
            };
            var requestContent = new JsonSerialization().ToJson(employee);
            var response = _httpClient.PostAsync("api/employee",
                new StringContent(requestContent, Encoding.UTF8, "application/json")).Result;

            Assert.AreEqual(HttpStatusCode.Created, response.StatusCode);
            return response.DeserializeContent<Employee>();
        }

        private static HttpResponseMessage PostCompensation(Compensation compensation)
        {
            var requestContent = new JsonSerialization().ToJson(compensation);
            return _httpClient.PostAsync("api/compensation",
                new StringContent(requestContent, Encoding.UTF8, "application/json")).Result;
        }
    }
}

