43:         public ReportingStructure GetReportingStructure(string id)
44:         {
45:             if (String.IsNullOrEmpty(id))
46:             {
47:                 return null;
48:             }
49: 
50:             var employee = _employeeRepository.GetAll().SingleOrDefault(item
 => item.EmployeeId == id);
51:             if (employee == null)
52:             {
53:                 return null;
54:             }
55: 
56:             return new ReportingStructure
57:             {
58:                 Employee = employee,
59:                 NumberOfReports = CountReports(employee)
60:             };
61:         }
