63:         // An iterative traversal avoids recursion limits and counts each em
ployee ID once.
64:         private static int CountReports(Employee employee)
65:         {
66:             var visitedEmployeeIds = new HashSet<string>(StringComparer.Ordi
nal);
67:             if (!String.IsNullOrEmpty(employee.EmployeeId))
68:             {
69:                 visitedEmployeeIds.Add(employee.EmployeeId);
70:             }
71: 
72:             var employeesToVisit = new Stack<Employee>();
73:             if (employee.DirectReports != null)
74:             {
75:                 foreach (var directReport in employee.DirectReports)
76:                 {
77:                     employeesToVisit.Push(directReport);
78:                 }
79:             }
80: 
81:             var numberOfReports = 0;
82:             while (employeesToVisit.Count > 0)
83:             {
84:                 var report = employeesToVisit.Pop();
85:                 if (report == null || String.IsNullOrEmpty(report.EmployeeId
) || !visitedEmployeeIds.Add(report.EmployeeId))
86:                 {
87:                     continue;
88:                 }
89: 
90:                 numberOfReports++;
91:                 if (report.DirectReports == null)
92:                 {
93:                     continue;
94:                 }
95: 
96:                 foreach (var directReport in report.DirectReports)
97:                 {
98:                     employeesToVisit.Push(directReport);
99:                 }
100:             }
101: 
102:             return numberOfReports;
103:         }
