105:         public Employee Replace(Employee originalEmployee, Employee newEmpl
oyee)
106:         {
107:             if(originalEmployee != null)
108:             {
109:                 _employeeRepository.Remove(originalEmployee);
110:                 if (newEmployee != null)
111:                 {
112:                     // ensure the original has been removed, otherwise EF w
ill complain another entity w/ same id already exists
113:                     _employeeRepository.SaveAsync().Wait();
114: 
115:                     _employeeRepository.Add(newEmployee);
116:                     // overwrite the new id with previous employee id
117:                     newEmployee.EmployeeId = originalEmployee.EmployeeId;
118:                 }
119:                 _employeeRepository.SaveAsync().Wait();
120:             }
121: 
122:             return newEmployee;
123:         }
